    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "When is all-dielectric mandatory?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Any span sharing structure with energized conductors. All-dielectric construction has no metallic element, so there is nothing to bond or ground and nothing to induce onto."
          }
        },
        {
          "@type": "Question",
          "name": "ADSS or figure 8?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "ADSS on long spans where no messenger exists and the cable has to carry itself. Figure 8 on shorter spans, where the integrated messenger is usually the cheaper way to get there. Send the span lengths and the loading class."
          }
        },
        {
          "@type": "Question",
          "name": "What span can you support?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Span rating depends on count, jacket and ice or wind loading class, so it is quoted per route rather than published as one number. Give us the longest span on the run and the loading class and we will spec against it."
          }
        },
        {
          "@type": "Question",
          "name": "Do you supply hybrid cable for tower sites?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, two copper and two fiber for FTTA and antenna sites, with IP68 waterproof connectors and terminal boxes in LC and MT types."
          }
        },
        {
          "@type": "Question",
          "name": "What is self-supporting aerial cable?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Self-supporting aerial cable is fiber cable that carries its own strength member, so it can be hung from poles or towers without a separate messenger wire. ADSS, all-dielectric self-supporting cable, contains no metal, which is why it suits spans that share structure with energized power lines. Vocom supplies ADSS aerial fiber cable build-to-order, with a standard lead time of 6 to 8 weeks."
          }
        }
      ]
    }
  ]
